addInteraction.example:
const { World } = kcds.world;
const { Chat } = kcds.core;

World.addInteraction(
  { position: new kcds.math.Vector3(-2820, -1320, 104), text: 'Ring the bell', radius: 3 },
  (ringer) => Chat.sendToAll(`${ringer.nickname} rings the bell`),
);

// Two keys on one prisoner's body.
World.addInteraction({ entity: prisoner, text: 'Search', key: 'primary_action' }, (searcher) => {
  Chat.sendToPlayer(searcher, 'Nothing on them.');
});
World.addInteraction({ entity: prisoner, text: 'Untie', key: 'script_action' }, (helper) => {
  Chat.sendToPlayer(helper, 'You untie the rope.');
});

// A hint on a horse that only its owner sees, wherever it walks.
const feed = World.addInteraction({ entity: horse, text: 'Feed', radius: 3 }, (feeder) => {
  Chat.sendToPlayer(feeder, 'The horse eats.');
});
feed.setPlayers([owner]);

addInteraction.exampleCs:
World.AddInteraction(new { position = new Vector3(-2820, -1320, 104), text = "Ring the bell", radius = 3 }, (JsValue ringer) => Chat.SendToAll($"{ringer["nickname"]} rings the bell"));

// Two keys on one prisoner's body.
World.AddInteraction(new { entity = prisoner, text = "Search", key = "primary_action" }, (JsValue searcher) =>
{
    Chat.SendToPlayer(searcher, "Nothing on them.");
});
World.AddInteraction(new { entity = prisoner, text = "Untie", key = "script_action" }, (JsValue helper) =>
{
    Chat.SendToPlayer(helper, "You untie the rope.");
});

// A hint on a horse that only its owner sees, wherever it walks.
var feed = World.AddInteraction(new { entity = horse, text = "Feed", radius = 3 }, (JsValue feeder) =>
{
    Chat.SendToPlayer(feeder, "The horse eats.");
});
