raycast.example:
// client: what the player looks at, within 4 metres
const { Key, Camera } = kcds.ui;

Key.bind('e', () => {
  const ray = Camera.rayFromScreen({ range: 4 });
  const hit = ray && kcds.world.World.raycast(ray.origin, ray.target, { mode: 'anything' });
  if (hit?.entityClass === 'AnimDoor') {
    console.info(`a door: ${hit.entityGuid}`);
  } else if (hit?.surface === 'mat_water') {
    console.info('water: cast the line');
  }
});

raycast.exampleCs:
// client: what the player looks at, within 4 metres
// (in the player's game the call takes (from, to, options))
Key.Bind("e", new Func<Task>(async () =>
{
    var ray = Camera.RayFromScreen(new { range = 4 });
    if (ray.IsNull)
    {
        return;
    }
    var hit = await World.Raycast(ray["origin"], ray["target"], new { mode = "anything" });
    if (hit.IsNull)
    {
        return;
    }
    if (hit["entityClass"].AsString() == "AnimDoor")
    {
        Log.Info($"a door: {hit["entityGuid"]}");
    }
    else if (hit["surface"].AsString() == "mat_water")
    {
        Log.Info("water: cast the line");
    }
}));

