traceAll.exampleCs:
// client: in the player's game the call takes (from, to, options)
var ray = Camera.RayFromScreen(new { range = 50 });
var hits = await World.TraceAll(ray["origin"], ray["target"], new { mode = "anything", maxHits = 4 });
Log.Info(string.Join(", ", hits.Select((hit) => $"{hit["kind"]} {hit["distance"].AsNumber():F1} m")));

